import{d as g,C as n,o as d,c as u,E as i,a3 as o}from"./chunks/framework.D4-ViStF.js";const x=JSON.parse('{"title":"兑为泽","description":"兑为泽，兑上兑下","frontmatter":{"title":"兑为泽","description":"兑为泽，兑上兑下","category":"hexagram","aliases":["兑","兑为泽"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-58.md","filePath":"yijing/hexagrams/hexagram-58.md","lastUpdated":1787800334000}'),h={name:"yijing/hexagrams/hexagram-58.md"},y=g({...h,setup(p){const a=[{id:"dui",term:"兑",pinyin:"duì",meaning:"喜悦，通「悦」。",context:"兑卦之名，两泽相连、彼此滋润之象。"},{id:"hedui",term:"和兑",pinyin:"hé duì",meaning:"平和真诚之悦。和，平和、不刻意。",context:"初九「和兑，吉」：发自内心的真诚连接。"},{id:"fudui",term:"孚兑",pinyin:"fú duì",meaning:"以诚信取悦、以诚信连接。孚，诚信。",context:"九二「孚兑，吉，悔亡」：说到做到。"},{id:"laidui",term:"来兑",pinyin:"lái duì",meaning:"主动前来讨好逢迎。来，主动、趋附。",context:"六三「来兑，凶」：为了取悦而讨好。"},{id:"shangdui",term:"商兑",pinyin:"shāng duì",meaning:"权衡商酌、犹豫未定之悦。商，商量、权衡。",context:"九四「商兑未宁」：在坚守与动摇之间权衡。"},{id:"jieji",term:"介疾",pinyin:"jiè jí",meaning:"坚守原则、隔绝邪疾。介，耿介坚守；疾，疾患、谄媚之弊。",context:"九四「介疾有喜」：短期痛苦，长期有喜。"},{id:"fuyubo",term:"孚于剥",pinyin:"fú yú bō",meaning:"诚信被剥蚀。剥，剥落、侵蚀。",context:"九五「孚于剥，有厉」：居正位更需防诚信被蚀。"},{id:"yindui",term:"引兑",pinyin:"yǐn duì",meaning:"引导喜悦、引领他人。引，牵引、引导。",context:"上六「引兑」：让喜悦成为文化传承。"},{id:"liize",term:"丽泽",pinyin:"lì zé",meaning:"两泽相连。丽，附着、相连。",context:"象传「丽泽，兑」：两片泽水互相滋润。"},{id:"pengyoujiangxi",term:"朋友讲习",pinyin:"péng yǒu jiǎng xí",meaning:"朋友之间切磋讲论学问。",context:"象传：喜悦不是独乐，是与朋友共修共进。"},{id:"gangzhongrouwai",term:"刚中柔外",pinyin:"gāng zhōng róu wài",meaning:"阳刚居中、柔顺在外。",context:"彖传：内有底线原则，外有温度包容。"},{id:"huiwang",term:"悔亡"},{id:"youli",term:"有厉",pinyin:"yǒu lì",meaning:"有危险、需警惕。",context:"九五「孚于剥，有厉」：诚信被蚀是最大的危险。"}],r=[{position:"初九",type:"yang",text:"和兑，吉。",xiang:"和兑之吉，行未疑也。",textModern:"真诚平和地与人连接，吉祥。",xiangModern:"和兑之所以吉，是因为行为坦荡真诚、无可置疑。"},{position:"九二",type:"yang",text:"孚兑，吉，悔亡。",xiang:"孚兑之吉，信志也。",textModern:"以诚信与人连接，吉祥，悔恨消亡。",xiangModern:"孚兑之所以吉，是因为内心有坚定的诚信之志。"},{position:"六三",type:"yin",text:"来兑，凶。",xiang:"来兑之凶，位不当也。",textModern:"主动前来讨好逢迎，凶。",xiangModern:"来兑之所以凶，是因为位置不当、动机不正。"},{position:"九四",type:"yang",text:"商兑未宁，介疾有喜。",xiang:"九四之喜，有庆也。",textModern:"在权衡犹豫中尚未安宁，但能坚守原则、隔绝邪疾，终有喜。",xiangModern:"九四的喜，是因为坚守原则而终有可庆之事。"},{position:"九五",type:"yang",text:"孚于剥，有厉。",xiang:"孚于剥，位正当也。",textModern:"诚信被剥蚀，有危险。",xiangModern:"孚于剥之所以危险，正是因为处在正位、更需警醒。"},{position:"上六",type:"yin",text:"引兑。",xiang:"上六引兑，未光也。",textModern:"引导喜悦，让喜悦延续与传承。",xiangModern:"上六的引导之悦，方向已明，尚待光大。"}];return(m,t)=>{const e=n("DaoHexagramViewer"),l=n("DaoHexagramYaoCards"),s=n("DaoKeywordCards");return d(),u("div",null,[i(e,{name:"兑为泽",fullName:"兑为泽",upper:"☱",lower:"☱",guaCi:"兑，亨，利贞。",pinyin:["duì","wéi","zé"],element:"金",direction:"西",virtue:"说",insight:"悦以先民，朋友讲习。",guaSlug:"58duiweizhe",lines:r}),t[0]||(t[0]=o('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>丽泽，兑。君子以朋友讲习。</p><ul><li><strong>丽泽，兑</strong> —— 丽是附着、相连。两片泽水相连，互相滋润，是兑（喜悦）之象。喜悦不是一个人的，是彼此照亮的。</li><li><strong>君子以朋友讲习</strong> —— 君子由此感悟：喜悦不是独乐，是与朋友一起切磋讲论、共修共进。</li></ul><p>「讲习」二字——<strong>讲</strong>是讲述、分享，把自己懂的讲出来；<strong>习</strong>是练习、切磋，在交流中反复磨。讲习，就是让喜悦在人与人的往来中流动起来。</p><blockquote><p><strong>丽泽之悦</strong>：两泽相连，你涨我润。真诚连接的喜悦，是越分享越多的喜悦；讨来的悦，是越索取越空的悦。</p></blockquote><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>兑，说也。刚中而柔外，说以利贞。是以顺乎天而应乎人。说以先民，民忘其劳。说以犯难，民忘其死。说之大，民劝矣哉。</p><p>逐句释义：</p><ul><li><strong>兑，说也</strong> —— 兑就是喜悦。</li><li><strong>刚中而柔外，说以利贞</strong> —— 阳刚居中、柔顺在外，这样的喜悦才利于守正。喜悦不是无原则的讨好，是内有底线、外有温度的坚定。</li><li><strong>是以顺乎天而应乎人</strong> —— 所以能顺应天道、应和人心。</li><li><strong>说以先民，民忘其劳</strong> —— 以喜悦引导民众，民众忘了劳苦。</li><li><strong>说以犯难，民忘其死</strong> —— 以喜悦面对患难，民众忘了生死。</li><li><strong>说之大，民劝矣哉</strong> —— 喜悦的力量之大，能让民众自觉勤勉。</li></ul><blockquote><p><strong>刚中柔外</strong>：刚，是有底线有原则——内容质量、文化匹配、长期主义；柔，是有温度有包容——商业模式、推广方式、生存压力。真正有力量的说，不是软塌塌的取悦，是「刚中柔外」的坚定与亲和。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',11)),i(l,{element:"金",guaSlug:"58duiweizhe",glossary:a,items:r}),t[1]||(t[1]=o('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初九-·-和兑-吉" tabindex="-1">初九 · 和兑，吉 <a class="header-anchor" href="#初九-·-和兑-吉" aria-label="Permalink to &quot;初九 · 和兑，吉&quot;">​</a></h3><ul><li><strong>和</strong> → 平和、发自内心</li><li><strong>兑</strong> → 喜悦、连接</li><li><strong>和兑</strong> → 真诚连接，不刻意、不带条件、不求回报</li></ul><p><strong>「行未疑也」</strong>——和兑之所以吉，是因为行为坦荡真诚，无可置疑。</p><blockquote><p>核心洞见：真诚连接不需要技巧。刻意讨好的「和」有破绽，发自内心的「和」无可疑。</p></blockquote><h3 id="九二-·-孚兑-吉-悔亡" tabindex="-1">九二 · 孚兑，吉，悔亡 <a class="header-anchor" href="#九二-·-孚兑-吉-悔亡" aria-label="Permalink to &quot;九二 · 孚兑，吉，悔亡&quot;">​</a></h3><ul><li><strong>孚</strong> → 诚信、信实</li><li><strong>孚兑</strong> → 以诚信连接、说到做到</li><li><strong>悔亡</strong> → 悔恨消亡</li></ul><p><strong>「信志也」</strong>——诚信不是表演，是心志。能做到的才承诺，承诺了就做到。</p><blockquote><p>核心洞见：说到做到，是最有力的取悦。信志立，悔亡。</p></blockquote><h3 id="六三-·-来兑-凶" tabindex="-1">六三 · 来兑，凶 <a class="header-anchor" href="#六三-·-来兑-凶" aria-label="Permalink to &quot;六三 · 来兑，凶&quot;">​</a></h3><ul><li><strong>来</strong> → 主动前来、趋附</li><li><strong>来兑</strong> → 主动讨好、逢迎</li></ul><p><strong>「位不当也」</strong>——以阴居阳，位置不当，动机不正。讨好是廉价的悦，换不来长久的信。</p><blockquote><p>核心洞见：不要为了短期的悦，失去长期的信。讨好是最贵的关系杠杆——你以为在买悦，其实在透支信。</p></blockquote><h3 id="九四-·-商兑未宁-介疾有喜" tabindex="-1">九四 · 商兑未宁，介疾有喜 <a class="header-anchor" href="#九四-·-商兑未宁-介疾有喜" aria-label="Permalink to &quot;九四 · 商兑未宁，介疾有喜&quot;">​</a></h3><ul><li><strong>商兑未宁</strong> → 权衡、犹豫、未定</li><li><strong>介疾</strong> → 耿介坚守，隔绝谄媚之弊</li><li><strong>有喜</strong> → 终有可庆之事</li></ul><p><strong>「有庆也」</strong>——允许犹豫，但要坚守；短期痛苦，长期有喜。</p><blockquote><p>核心洞见：犹豫不是问题，动摇才是。介疾者，短期痛，长期喜。</p></blockquote><h3 id="九五-·-孚于剥-有厉" tabindex="-1">九五 · 孚于剥，有厉 <a class="header-anchor" href="#九五-·-孚于剥-有厉" aria-label="Permalink to &quot;九五 · 孚于剥，有厉&quot;">​</a></h3><ul><li><strong>孚于剥</strong> → 诚信被剥蚀</li><li><strong>有厉</strong> → 有危险</li></ul><p><strong>「位正当也」</strong>——越居正位，越要警惕。顺境、捧场、成功，都在一点一点剥蚀诚信。</p><blockquote><p>核心洞见：诚信最难守的时候，是看似一切都好的时候。孚于剥之厉，不在外敌，在自蚀。</p></blockquote><h3 id="上六-·-引兑" tabindex="-1">上六 · 引兑 <a class="header-anchor" href="#上六-·-引兑" aria-label="Permalink to &quot;上六 · 引兑&quot;">​</a></h3><ul><li><strong>引</strong> → 引导、牵引</li><li><strong>引兑</strong> → 引导喜悦、引领他人</li></ul><p><strong>「未光也」</strong>——方向已明，尚待光大。引导他人、传承文化，让喜悦成为众人的喜悦。</p><blockquote><p>核心洞见：喜悦的终极形态不是占有，是传承。把真诚连接做成文化，是兑卦的终点。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',26)),i(s,{title:"字词释义",items:[{term:"兑",pinyin:["duì"],meaning:"喜悦，通「悦」；也指交换、兑现。兑卦的核心是真诚连接的喜悦。"},{term:"丽泽",pinyin:["lì","zé"],meaning:"两泽相连。丽，附着、相连；泽水相连，互相滋润。"},{term:"朋友讲习",pinyin:["péng","yǒu","jiǎng","xí"],meaning:"朋友之间切磋讲论学问。讲，讲述分享；习，练习切磋。"},{term:"刚中柔外",pinyin:["gāng","zhōng","róu","wài"],meaning:"阳刚居中、柔顺在外；内有底线原则，外有温度包容。"},{term:"和兑",pinyin:["hé","duì"],meaning:"平和真诚之悦；发自内心的连接，不刻意。"},{term:"孚兑",pinyin:["fú","duì"],meaning:"以诚信取悦；说到做到。孚，诚信、信实。"},{term:"来兑",pinyin:["lái","duì"],meaning:"主动前来讨好逢迎；为悦而悦，动机不正。"},{term:"商兑",pinyin:["shāng","duì"],meaning:"权衡商酌、犹豫未定之悦。商，商量、权衡。"},{term:"介疾",pinyin:["jiè","jí"],meaning:"坚守原则、隔绝邪疾。介，耿介坚守；疾，疾患、谄媚之弊。"},{term:"孚于剥",pinyin:["fú","yú","bō"],meaning:"诚信被剥蚀。剥，剥落、侵蚀；诚信在顺境中慢慢流失。"},{term:"引兑",pinyin:["yǐn","duì"],meaning:"引导喜悦、引领他人；让喜悦延续与传承。"},{term:"悔亡"},{term:"有厉",pinyin:["yǒu","lì"],meaning:"有危险、需警惕。"}]}),t[2]||(t[2]=o('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>兑卦讲的是<strong>喜悦之道——真诚连接，说到做到</strong>。上兑下兑，两泽相连（丽泽），彼此滋润。卦辞「兑，亨，利贞」点明：喜悦能亨通，但必须守正——不是无原则的讨好，是「刚中柔外」的真诚连接。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>喜悦最容易走岔路。一岔，就变成六三的「来兑」——讨好、逢迎、为了取悦而失去原则。兑卦给喜悦立了界：</p><ul><li><strong>对内</strong>：刚中——有底线、有原则，守内容质量、文化匹配、长期主义</li><li><strong>对外</strong>：柔外——有温度、有包容，商业模式、推广方式、生存压力都可以灵活</li></ul><p>说到做到是信，真诚连接是和。信与和，才是喜悦能长久的根基。</p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li>初九<strong>和兑</strong>：与人连接，发自内心，不刻意、不套路</li><li>九二<strong>孚兑</strong>：能做到的才承诺，承诺了就做到</li><li>六三<strong>来兑</strong>：不讨好，不为短期的悦失去长期的信</li><li>九四<strong>介疾</strong>：允许犹豫，但坚守原则，短期痛苦长期有喜</li><li>九五<strong>孚于剥</strong>：越顺境越自省，防诚信被剥蚀</li><li>上六<strong>引兑</strong>：把真诚连接做成文化，引导更多人加入</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>兑卦的完整地图：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞要点</th><th>功课</th><th>关键词</th></tr></thead><tbody><tr><td>卦辞</td><td>兑，亨，利贞</td><td>喜悦守正，刚中柔外</td><td>真诚连接</td></tr><tr><td>初九</td><td>和兑，吉</td><td>发自内心，不刻意</td><td>真诚连接，行未疑</td></tr><tr><td>九二</td><td>孚兑，吉，悔亡</td><td>说到做到，信志立悔亡</td><td>诚信之志</td></tr><tr><td>六三</td><td>来兑，凶</td><td>不讨好，不为短悦失长信</td><td>位不当，动机不正</td></tr><tr><td>九四</td><td>商兑未宁，介疾有喜</td><td>允许犹豫，坚守原则</td><td>短期痛，长期喜</td></tr><tr><td>九五</td><td>孚于剥，有厉</td><td>越顺境越防诚信被蚀</td><td>自蚀之厉</td></tr><tr><td>上六</td><td>引兑</td><td>引导他人，传承文化</td><td>未光，方向已明</td></tr></tbody></table><p>核心洞见：</p><ol><li><strong>真诚连接</strong>——喜悦的根是真诚，不是讨好</li><li><strong>说到做到</strong>——能做到的才承诺，承诺了就做到</li><li><strong>刚中柔外</strong>——内有底线原则，外有温度包容</li><li><strong>来兑之凶</strong>——为短期的悦，透支长期的信，最贵</li><li><strong>介疾有喜</strong>——允许犹豫，坚守原则，短期痛苦长期有喜</li><li><strong>孚于剥之厉</strong>——诚信最难守的时候，是看似一切都好的时候</li><li><strong>引兑之终</strong>——喜悦的终极形态不是占有，是传承</li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>兑卦是昇哥创业的处世哲学——<strong>真诚连接，说到做到</strong>：</p><ul><li><strong>登录模块设计</strong> → 初九「和兑」：不强制注册、不诱导、不夸大。让用户发自内心地来，而不是被套路来。</li><li><strong>团队招聘</strong> → 九二「孚兑」：文化匹配优先于能力堆砌。能做到的才承诺，承诺了就做到，人才才信你。</li><li><strong>融资谈判</strong> → 九四「介疾」：内容质量不妥协。可以权衡、可以犹豫，但内容质量的底线不松——短期谈崩的痛苦，换长期品牌之喜。</li><li><strong>试用期考核</strong> → 上六「引兑」：不达标就挂掉，不纠结。该放手时放手，对留下的人和离开的人都是真诚。</li></ul><p>六爻从初九到上六，是一条成长线：先是<strong>真诚连接</strong>，再是<strong>说到做到</strong>，然后<strong>拒绝讨好</strong>、<strong>坚守原则</strong>、<strong>防诚信被蚀</strong>，最后把这份文化<strong>引向更多人</strong>。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：巽（第五十七卦）、涣（第五十九卦）、节（第六十卦）</li><li>兑与巽的连结：兑巽相对——兑为泽，巽为风。泽喜而风入，喜悦敞开，柔顺深入；泽的悦养出风的行，风的入带来泽的盈。</li><li>兑与涣节的连结：兑而后涣——喜悦让人心开，人心开而涣散可解；喜悦也需节制，节卦教喜悦有度，防止乐极。</li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a></li></ul>',20))])}}});export{x as __pageData,y as default};
